--
-- Name: create_tenant_schema(text); Type: FUNCTION; Schema: public; Owner: unicampus
--

CREATE FUNCTION public.create_tenant_schema(p_slug text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_schema TEXT := 'tenant_' || p_slug;
BEGIN
  EXECUTE format('CREATE SCHEMA IF NOT EXISTS %I', v_schema);
END;
$$;


ALTER FUNCTION public.create_tenant_schema(p_slug text) OWNER TO unicampus;

